python3 -I -c 'M="Problems.Hodge.Millennium";T=[];C="import sys,json,itertools as I,subprocess as S,tempfile,re,os\nJ=json.dumps\nQ=lambda:\"python3 -I -c %cM=%s;T=%s;C=%s;exec(C)%c \\\"$@\\\"\\n\"%(39,J(M),J(T),J(C),39)\nA=\"exact?|intro|rfl|apply?|aesop|simp_all\".split(\"|\")\ndef G(b):\n n=1\n for x in b:n=n*257+x+1\n return hex(n)[2:]\ndef D(g):\n n=int(g,16);a=[]\n while n>1:n,r=divmod(n-1,257);a.append(r)\n assert n==1;return bytes(a[::-1])\ndef P(k,t):\n a=[]\n while k:k,r=divmod(k-1,len(A));a.insert(0,A[r])\n return \"import \"+M+\"\\ntheorem uto_m7 : \"+t+\" := by\\n  \"+\"\\n  \".join(a)+\"\\n#print axioms uto_m7\\n\"\ndef ok(s):\n q=chr(39)+\"uto_m7\"+chr(39);m=re.fullmatch(q+r\" depends on axioms: \\[([^\\]]*)\\]\",s.strip())\n return set(m[1].replace(\",\",\" \").split())<=set(\"propext Classical.choice Quot.sound\".split()) if m else s.strip()==q+\" does not depend on any axioms\"\nm,*v=sys.argv[1:] or [\"self\"]\nif m==\"self\":print(Q(),end=\"\")\nelif m==\"encode\":print(G(Q().encode()))\nelif m==\"decode\":sys.stdout.buffer.write(D(v[0]))\nelif m==\"status\":print(J([M,T,\"PENDING\" if T else \"INCOMPLETE\"]))\nelif not T:sys.exit(\"INCOMPLETE\")\nelif m==\"emit\":k,i=map(int,v);assert k>0;print(P(k,T[i]),end=\"\")\nelif m==\"search\":\n f,b=v;b=int(b);assert b>=0 and not os.path.exists(f)\n with tempfile.TemporaryDirectory(dir=\".\") as d:\n  p=d+\"/M.lean\"\n  for n in I.count(1):\n   if b and n>b:sys.exit(\"UNKNOWN\")\n   for t,k in I.product(T,range(1,n+1)):\n    z=P(k,t);open(p,\"w\").write(z)\n    try:r=S.run([\"lake\",\"env\",\"lean\",p],capture_output=True,text=True,timeout=n+60)\n    except FileNotFoundError:sys.exit(\"NO_LAKE\")\n    except S.TimeoutExpired:continue\n    if not r.returncode and ok(r.stdout) and not r.stderr:\n     with open(f,\"x\") as w:w.write(z)\n     sys.exit(\"REVIEW\")\nelse:sys.exit(2)";exec(C)' "$@"
